insert into public.movies (tmdb_id, title, year, poster_path, genres, overview) values
  (693134, 'Dune: Part Two', 2024, '/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', array['Science Fiction', 'Adventure']::text[], 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a path of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, Paul endeavors to prevent a terrible future only he can foresee.'),
  (666277, 'Past Lives', 2023, '/k3waqVXSnvCZWfJYNtdamTgTtTA.jpg', array['Drama', 'Romance']::text[], 'After decades apart, childhood friends Nora and Hae Sung are reunited in New York for one fateful weekend as they confront notions of destiny, love, and the choices that make a life.'),
  (569094, 'Spider-Man: Across the Spider-Verse', 2023, '/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', array['Animation', 'Action']::text[], 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.'),
  (872585, 'Oppenheimer', 2023, '/8Gxv8gSFCU0XGDykEGv7zR1n2ua.jpg', array['Drama', 'History']::text[], 'The story of J. Robert Oppenheimer''s role in the development of the atomic bomb during World War II.'),
  (840430, 'The Holdovers', 2023, '/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', array['Comedy', 'Drama']::text[], 'A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.'),
  (545611, 'Everything Everywhere All at Once', 2022, '/u68AjlvlutfEIcpmbYpKcdi09ut.jpg', array['Action', 'Comedy']::text[], 'An aging Chinese immigrant is swept up in an insane adventure, where she alone can save what''s important to her by connecting with the lives she could have led in other universes.'),
  (496243, 'Parasite', 2019, '/7IiTTgloJzvGI1TAYymCfbfl3vT.jpg', array['Thriller', 'Drama']::text[], 'All unemployed, Ki-taek''s family takes peculiar interest in the wealthy and glamorous Parks for their livelihood until they get entangled in an unexpected incident.'),
  (244786, 'Whiplash', 2014, '/7fn624j5lj3xTme2SgiLCeuedmO.jpg', array['Drama', 'Music']::text[], 'Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.'),
  (915935, 'Anatomy of a Fall', 2023, '/1ho0d4LNZw3Y0voeKmSvPSgJOJ2.jpg', array['Drama', 'Mystery']::text[], 'A woman is suspected of her husband''s murder, and their blind son faces a moral dilemma as the sole witness.'),
  (792307, 'Poor Things', 2023, '/kCGlIMHnOm8JPXq3rXM6c5wMxcT.jpg', array['Comedy', 'Science Fiction']::text[], 'Brought back to life by an unorthodox scientist, a young woman runs off with a lawyer on a whirlwind adventure across the continents. Free from the prejudices of her times, she grows steadfast in her purpose to stand for equality and liberation.'),
  (157336, 'Interstellar', 2014, '/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', array['Science Fiction', 'Drama']::text[], 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.'),
  (155, 'The Dark Knight', 2008, '/qJ2tW6WMUDux911r6m7haRef0WH.jpg', array['Action', 'Crime']::text[], 'Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.'),
  (419430, 'Get Out', 2017, '/tFXcEccSQMf3lfhfXKSU9iRBpa3.jpg', array['Horror', 'Thriller']::text[], 'Chris and his girlfriend Rose go upstate to visit her parents for the weekend. At first, Chris reads the family''s overly accommodating behavior as nervous attempts to deal with their daughter''s interracial relationship, but as the weekend progresses, a series of increasingly disturbing discoveries lead him to a truth that he never could have imagined.'),
  (313369, 'La La Land', 2016, '/uDO8zWDhfWwoFdKS4fzkUJt0Rf0.jpg', array['Romance', 'Music']::text[], 'Mia, an aspiring actress, serves lattes to movie stars in between auditions and Sebastian, a jazz musician, scrapes by playing cocktail party gigs in dingy bars, but as success mounts they are faced with decisions that begin to fray the fragile fabric of their love affair, and the dreams they worked so hard to maintain in each other threaten to rip them apart.'),
  (27205, 'Inception', 2010, '/xlaY2zyzMfkhk0HSC5VUwzoZPU1.jpg', array['Science Fiction', 'Action']::text[], 'Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.'),
  (680, 'Pulp Fiction', 1994, '/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', array['Crime', 'Thriller']::text[], 'A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.'),
  (238, 'The Godfather', 1972, '/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', array['Crime', 'Drama']::text[], 'Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.'),
  (278, 'The Shawshank Redemption', 1994, '/9cqNxx0GxF0bflZmeSMuL5tnGzr.jpg', array['Drama']::text[], 'Imprisoned in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.'),
  (550, 'Fight Club', 1999, '/jSziioSwPVrOy9Yow3XhWIBDjq1.jpg', array['Drama', 'Thriller']::text[], 'A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.'),
  (603, 'The Matrix', 1999, '/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', array['Science Fiction', 'Action']::text[], 'Set in the 22nd century, The Matrix tells the story of a computer hacker who joins a group of underground insurgents fighting the vast and powerful computers who now rule the earth.'),
  (129, 'Spirited Away', 2001, '/39wmItIWsg5sZMyRUHLkWBcuVCM.jpg', array['Animation', 'Fantasy']::text[], 'A young girl, Chihiro, becomes trapped in a strange new world of spirits. When her parents undergo a mysterious transformation, she must call upon the courage she never knew she had to free her family.'),
  (346698, 'Barbie', 2023, '/iuFNMS8U5cb6xfzi51Dbkovj7vM.jpg', array['Comedy', 'Fantasy']::text[], 'Barbie and Ken are having the time of their lives in the colorful and seemingly perfect world of Barbie Land. However, when they get a chance to go to the real world, they soon discover the joys and perils of living among humans.'),
  (862, 'Toy Story', 1995, '/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', array['Animation', 'Family']::text[], 'Led by Woody, Andy''s toys live happily in his room until Andy''s birthday brings Buzz Lightyear onto the scene. Afraid of losing his place in Andy''s heart, Woody plots against Buzz. But when circumstances separate Buzz and Woody from their owner, the duo eventually learns to put aside their differences.'),
  (597, 'Titanic', 1997, '/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', array['Romance', 'Drama']::text[], '101-year-old Rose DeWitt Bukater tells the story of her life aboard the Titanic, 84 years later. A young Rose boards the ship with her mother and fiancé. Meanwhile, Jack Dawson and Fabrizio De Rossi win third-class tickets aboard the ship. Rose tells the whole story from Titanic''s departure through to its death—on its first and last voyage—on April 15, 1912.'),
  (37799, 'The Social Network', 2010, '/n0ybibhJtQ5icDqTp8eRytcIHJx.jpg', array['Drama']::text[], 'In 2003, Harvard undergrad and computer programmer Mark Zuckerberg begins work on a new concept that eventually turns into the global social network known as Facebook. Six years later, Mark is one of the youngest billionaires ever, but his unprecedented success leads to both personal and legal complications when he ends up on the receiving end of two lawsuits, one involving his former friend.'),
  (152601, 'Her', 2013, '/eCOtqtfvn7mxGl6nfmq4b1exJRc.jpg', array['Romance', 'Science Fiction']::text[], 'In the not so distant future, Theodore, a lonely writer, purchases a newly developed operating system designed to meet the user''s every need. To Theodore''s surprise, a romantic relationship develops between him and his operating system. This unconventional love story blends science fiction and romance in a sweet tale that explores the nature of love and the ways that technology isolates and connects us all.'),
  (329865, 'Arrival', 2016, '/pEzNVQfdzYDzVK0XqxERIw2x2se.jpg', array['Science Fiction', 'Drama']::text[], 'Taking place after alien crafts land around the world, an expert linguist is recruited by the military to determine whether they come in peace or are a threat.'),
  (76341, 'Mad Max: Fury Road', 2015, '/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg', array['Action', 'Adventure']::text[], 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order.'),
  (546554, 'Knives Out', 2019, '/pThyQovXQrw2m0s9x82twj48Jq4.jpg', array['Mystery', 'Comedy']::text[], 'When renowned crime novelist Harlan Thrombey is found dead at his estate just after his 85th birthday, the inquisitive and debonair Detective Benoit Blanc is mysteriously enlisted to investigate. From Harlan''s dysfunctional family to his devoted staff, Blanc sifts through a web of red herrings and self-serving lies to uncover the truth behind Harlan''s untimely death.'),
  (391713, 'Lady Bird', 2017, '/gl66K7zRdtNYGrxyS2YDUP5ASZd.jpg', array['Comedy', 'Drama']::text[], 'Lady Bird McPherson, a strong willed, deeply opinionated, artistic 17 year old comes of age in Sacramento. Her relationship with her mother and her upbringing are questioned and tested as she plans to head off to college.'),
  (376867, 'Moonlight', 2016, '/qLnfEmPrDjJfPyyddLJPkXmshkp.jpg', array['Drama']::text[], 'The tender, heartbreaking story of a young man’s struggle to find himself, told across three defining chapters in his life as he experiences the ecstasy, pain, and beauty of falling in love, while grappling with his own sexuality.'),
  (150540, 'Inside Out', 2015, '/2H1TmgdfNtsKlU9jKdeNyYL5y8T.jpg', array['Animation', 'Family']::text[], 'When 11-year-old Riley moves to a new city, her Emotions team up to help her through the transition. Joy, Fear, Anger, Disgust and Sadness work together, but when Joy and Sadness get lost, they must journey through unfamiliar places to get back home.'),
  (14160, 'Up', 2009, '/mFvoEwSfLqbcWwFsDjQebn9bzFe.jpg', array['Animation', 'Adventure']::text[], 'Carl Fredricksen spent his entire life dreaming of exploring the globe and experiencing life to its fullest. But at age 78, life seems to have passed him by, until a twist of fate (and a persistent 8-year old Wilderness Explorer named Russell) gives him a new lease on life.'),
  (354912, 'Coco', 2017, '/6Ryitt95xrO8KXuqRGm1fUuNwqF.jpg', array['Animation', 'Family']::text[], 'Despite his family’s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel''s family history.'),
  (120467, 'The Grand Budapest Hotel', 2014, '/eWdyYQreja6JGCzqHWXpWHDrrPo.jpg', array['Comedy', 'Drama']::text[], 'The Grand Budapest Hotel tells of a legendary concierge at a famous European hotel between the wars and his friendship with a young employee who becomes his trusted protégé. The story involves the theft and recovery of a priceless Renaissance painting, the battle for an enormous family fortune and the slow and then sudden upheavals that transformed Europe during the first half of the 20th century.'),
  (335984, 'Blade Runner 2049', 2017, '/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', array['Science Fiction', 'Drama']::text[], 'Thirty years after the events of the first film, a new blade runner, LAPD Officer K, unearths a long-buried secret that has the potential to plunge what''s left of society into chaos. K''s discovery leads him on a quest to find Rick Deckard, a former LAPD blade runner who has been missing for 30 years.'),
  (361743, 'Top Gun: Maverick', 2022, '/n0YuM4f5lvGAP6MAW2kBIzugXnc.jpg', array['Action', 'Drama']::text[], 'After more than thirty years of service as one of the Navy’s top aviators, and dodging the advancement in rank that would ground him, Pete “Maverick” Mitchell finds himself training a detachment of TOP GUN graduates for a specialized mission the likes of which no living pilot has ever seen.'),
  (331482, 'Little Women', 2019, '/yn5ihODtZ7ofn8pDYfxCmxh8AXI.jpg', array['Drama', 'Romance']::text[], 'Four sisters come of age in America in the aftermath of the Civil War.'),
  (194, 'Amélie', 2001, '/nSxDa3M9aMvGVLoItzWTepQ5h5d.jpg', array['Comedy', 'Romance']::text[], 'At a tiny Parisian café, the adorable yet painfully shy Amélie accidentally discovers a gift for helping others. Soon Amelie is spending her days as a matchmaker, guardian angel, and all-around do-gooder. But when she bumps into a handsome stranger, will she find the courage to become the star of her very own love story?'),
  (6977, 'No Country for Old Men', 2007, '/6d5XOczc226jECq0LIX0siKtgHR.jpg', array['Crime', 'Thriller']::text[], 'Llewelyn Moss stumbles upon dead bodies, $2 million and a hoard of heroin in a Texas desert, but methodical killer Anton Chigurh comes looking for it, with local sheriff Ed Tom Bell hot on his trail. The roles of prey and predator blur as the violent pursuit of money and justice collide.'),
  (769, 'Goodfellas', 1990, '/9OkCLM73MIU2CrKZbqiT8Ln1wY2.jpg', array['Crime', 'Drama']::text[], 'The true story of Henry Hill, a half-Irish, half-Sicilian Brooklyn kid who is adopted by neighbourhood gangsters at an early age and climbs the ranks of a Mafia family under the guidance of Jimmy Conway.'),
  (329, 'Jurassic Park', 1993, '/d9mtMGQDLANKieb9PbD3yK7xxzo.jpg', array['Adventure', 'Science Fiction']::text[], 'A wealthy entrepreneur secretly creates a theme park featuring living dinosaurs drawn from prehistoric DNA. Before opening day, he invites a team of experts and his two eager grandchildren to experience the park and help calm anxious investors. However, the park is anything but amusing as the security systems go off-line and the dinosaurs escape.'),
  (120, 'The Lord of the Rings: The Fellowship of the Ring', 2001, '/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', array['Fantasy', 'Adventure']::text[], 'Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.'),
  (105, 'Back to the Future', 1985, '/vN5B5WgYscRGcQpVhHl6p9DDTP0.jpg', array['Science Fiction', 'Comedy']::text[], 'Eighties teenager Marty McFly is accidentally sent back in time to 1955, inadvertently disrupting his parents'' first meeting and attracting his mother''s romantic interest. Marty must repair the damage to history by rekindling his parents'' romance and - with the help of his eccentric inventor friend Doc Brown - return to 1985.'),
  (2062, 'Ratatouille', 2007, '/t3vaWRPSf6WjDSamIkKDs1iQWna.jpg', array['Animation', 'Comedy']::text[], 'In one of Paris''s finest restaurants, Remy, a determined young rat, dreams of becoming a renowned French chef. Torn between his family''s wishes and his true calling, Remy and his pal Linguini set in motion a hilarious chain of events that turns the City of Lights upside down.'),
  (44214, 'Black Swan', 2010, '/viWheBd44bouiLCHgNMvahLThqx.jpg', array['Thriller', 'Drama']::text[], 'A committed dancer struggles to maintain her sanity after winning the lead role in a production of Tchaikovsky''s "Swan Lake."'),
  (37165, 'The Truman Show', 1998, '/vuza0WqY239yBXOadKlGwJsZJFE.jpg', array['Comedy', 'Drama']::text[], 'In a picture-perfect seaside town, an insurance salesman begins to realize that his entire existence may be staged and observed by a vast unseen audience as part of a long-running real-time reality TV show.'),
  (8363, 'Superbad', 2007, '/ek8e8txUyUwd2BNqj6lFEerJfbq.jpg', array['Comedy']::text[], 'Two co-dependent high school seniors are forced to deal with separation anxiety after their plan to stage a booze-soaked party goes awry.'),
  (493922, 'Hereditary', 2018, '/4GFPuL14eXi66V96xBWY73Y9PfR.jpg', array['Horror', 'Mystery']::text[], 'When the matriarch of the Graham family passes away, her daughter begins to unravel cryptic and increasingly terrifying secrets about her ancestry.'),
  (965150, 'Aftersun', 2022, '/evKz85EKouVbIr51zy5fOtpNRPg.jpg', array['Drama']::text[], 'Sophie reflects on the shared joy and private melancholy of a holiday she took with her father twenty years earlier. Memories fill the gaps between camcorder footages as she tries to reconcile the father she knew with the troubled man she didn''t.'),
  (937287, 'Challengers', 2024, '/H6vke7zGiuLsz4v4RPeReb9rsv.jpg', array['Drama', 'Romance']::text[], 'Tennis player turned coach Tashi has taken her husband, Art, and transformed him into a world-famous Major champion. To jolt him out of his recent losing streak, she signs him up for a "Challenger" event — close to the lowest level of pro tournament — where he finds himself standing across the net from his former best friend and Tashi''s former boyfriend.'),
  (402431, 'Wicked', 2024, '/xDGbZ0JJ3mYaGKy4Nzd9Kph6M9L.jpg', array['Fantasy', 'Music']::text[], 'In the land of Oz, ostracized and misunderstood green-skinned Elphaba is forced to share a room with the popular aristocrat Glinda at Shiz University, and the two''s unlikely friendship is tested as they begin to fulfill their respective destinies as Glinda the Good and the Wicked Witch of the West.'),
  (1022789, 'Inside Out 2', 2024, '/vpnVM9B6NMmQpWeZvzLvDESb2QY.jpg', array['Animation', 'Family']::text[], 'Teenager Riley''s mind headquarters is undergoing a sudden demolition to make room for something entirely unexpected: new Emotions! Joy, Sadness, Anger, Fear and Disgust, who’ve long been running a successful operation by all accounts, aren’t sure how to feel when Anxiety shows up. And it looks like she’s not alone.'),
  (98, 'Gladiator', 2000, '/aDb548BOkFfI4nFm0kx8A3Ezh7H.jpg', array['Action', 'Drama']::text[], 'After the death of Emperor Marcus Aurelius, his devious son takes power and demotes Maximus, one of Rome''s most capable generals who Marcus preferred. Eventually, Maximus is forced to become a gladiator and battle to the death against other men for the amusement of paying audiences.'),
  (299534, 'Avengers: Endgame', 2019, '/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', array['Action', 'Science Fiction']::text[], 'After the devastating events of Avengers: Infinity War, the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos'' actions and restore order to the universe once and for all, no matter what consequences may be in store.'),
  (808, 'Shrek', 2001, '/iB64vpL3dIObOtMZgX3RqdVdQDc.jpg', array['Animation', 'Comedy']::text[], 'It ain''t easy bein'' green -- especially if you''re a likable (albeit smelly) ogre named Shrek. On a mission to retrieve a gorgeous princess from the clutches of a fire-breathing dragon, Shrek teams up with an unlikely compatriot -- a wisecracking donkey.'),
  (274, 'The Silence of the Lambs', 1991, '/uS9m8OBk1A8eM9I042bx8XXpqAq.jpg', array['Thriller', 'Crime']::text[], 'Clarice Starling is a top student at the FBI''s training academy.  Jack Crawford wants Clarice to interview Dr. Hannibal Lecter, a brilliant psychiatrist who is also a violent psychopath, serving life behind bars for various acts of murder and cannibalism.  Crawford believes that Lecter may have insight into a case and that Starling, as an attractive young woman, may be just the bait to draw him out.'),
  (128, 'Princess Mononoke', 1997, '/cMYCDADoLKLbB83g4WnJegaZimC.jpg', array['Animation', 'Fantasy']::text[], 'Ashitaka, a prince of the disappearing Emishi people, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.'),
  (531428, 'Portrait of a Lady on Fire', 2019, '/2LquGwEhbg3soxSCs9VNyh5VJd9.jpg', array['Drama', 'Romance']::text[], 'On an isolated island in Brittany at the end of the eighteenth century, a female painter is obliged to paint a wedding portrait of a young woman.'),
  (324857, 'Spider-Man: Into the Spider-Verse', 2018, '/iiZZdoQBEYBv6id8su7ImL0oCbD.jpg', array['Animation', 'Action']::text[], 'Struggling to find his place in the world while juggling school and family, Brooklyn teenager Miles Morales is unexpectedly bitten by a radioactive spider and develops unfathomable powers just like the one and only Spider-Man. While wrestling with the implications of his new abilities, Miles discovers a super collider created by the madman Wilson "Kingpin" Fisk, causing others from across the Spider-Verse to be inadvertently transported to his dimension.')
