-- Demo movie catalog, generated from src/data/movies.json.
-- Loaded automatically by `supabase db reset`. On a hosted project, paste
-- it into the SQL editor once after running the migrations.
-- Safe to re-run: existing movies are updated, not duplicated.

on conflict (tmdb_id) do update set
  title = excluded.title,
  year = excluded.year,
  poster_path = excluded.poster_path,
  genres = excluded.genres,
  overview = excluded.overview,
  cached_at = now();
